        result = "#version 140\n"
                 "\n"
                 "in sampler2D data;\n"
                 "\n"
                 "void main()\n"
                 "{\n"
                 "}\n";

        break;
    }

    case TEST_ITERATION_INVALID_STRUCTURE_INPUT:
    {
        result = "#version 140\n"
                 "\n"
                 "in struct\n"
                 "{\n"
                 "    vec4 test;\n"
                 "} data;\n"
                 "\n"
                 "void main()\n"
                 "{\n"
                 "}\n";

