        gl.drawArrays(GL_POINTS, 0, count0);

        gl.uniform1ui(streamLoc, 1);
        gl.drawArrays(GL_POINTS, 0, count1);

        gl.uniform1ui(streamLoc, 2);
        gl.drawArrays(GL_POINTS, 0, count2);

        gl.uniform1ui(streamLoc, 3);
