                        << fb[idx].y() << " " << fb[idx].z() << tcu::TestLog::EndMessage;
                    status = false;
                }
            }
        }
        // middle horizontal line should be black
        for (int y = height / 2 - 2; y < height / 2 + 2; ++y)
        {
            for (int x = 0; x < width; ++x)
            {
                const int idx = y * width + x;
                if (!ColorEqual(fb[idx], vec3(0), g_color_eps))
