            glDeleteShader(sh);
            const char *const src[2] = {kGLSLVer, vs.c_str()};
            glShaderSource(sh, 2, src, NULL);
            glCompileShader(sh);
        }
        if (!fs.empty())
        {
            const GLuint sh = glCreateShader(GL_FRAGMENT_SHADER);
            glAttachShader(p, sh);
            glDeleteShader(sh);
            const char *const src[2] = {kGLSLVer, fs.c_str()};
            glShaderSource(sh, 2, src, NULL);
            glCompileShader(sh);
        }

        return p;
    }

