                        << fb[idx].y() << " " << fb[idx].z() << tcu::TestLog::EndMessage;
                    status = false;
                }
            }
        }

        return status;
    }

    bool IsEqual(vec4 a, vec4 b)
    {
        return (a.x() == b.x()) && (a.y() == b.y()) && (a.z() == b.z()) && (a.w() == b.w());
    }

    bool IsEqual(uvec4 a, uvec4 b)
    {
        return (a.x() == b.x()) && (a.y() == b.y()) && (a.z() == b.z()) && (a.w() == b.w());
    }
};

