class FunctionalTest : public deqp::TestCase
{
public:
    /* Public member functions */
    FunctionalTest(deqp::Context &context);

    virtual tcu::TestNode::IterateResult iterate();

private:
    /* Private member functions */
    FunctionalTest(const FunctionalTest &other);
    FunctionalTest &operator=(const FunctionalTest &other);

    glw::GLfloat testTime(bool shall_flush_on_release);

    /** @brief Draw Setup class to encapsulate context with framebuffer and shader program.
     *
     *  The context and within framebuffer, renderbuffer, vertex array object,
     *  shader program is created on the construction. Using makeCurrent() one can swith to
     *  the encapsulated context. With draw() member function one can draw full screen quad.
     *  All objects are deallocated during object destruction.
     *
     *  Context will flush or will not flush on makeCurrent() switch depending on
     *  constructor setup shall_flush_on_release.
     */
    class DrawSetup
    {
    public:
        DrawSetup(deqp::Context &test_context, bool shall_flush_on_release);
        ~DrawSetup();

        void makeCurrent();
        void draw();

    private:
        deqp::Context &m_test_context; //!< Test main context.
        glu::RenderContext *m_context; //!< Render context of this draw setup.
        glw::GLuint m_fbo;             //!< OpenGL framebuffer object identifier (in m_context).
        glw::GLuint m_rbo;             //!< OpenGL renderbuffer object identifier (in m_context).
        glw::GLuint m_vao;             //!< OpenGL vertex array object identifier (in m_context).
        glw::GLuint m_po;              //!< OpenGL GLSL program object identifier (in m_context).

        static const glw::GLuint s_view_size; //!< Framebuffer size (default 256).
        static const glw::GLchar s_vertex_shader
            []; //!< Vertex shader source code (it draws quad using triangle strip depending on gl_VertexID).
        static const glw::GLchar s_fragment_shader[]; //!< Fragment shader source code (setup vec4(1.0) as a color).

        void createContext(bool shall_flush_on_release);
        void createView();
        void createGeometry();
        void createProgram();
    };
};



// === Member function implementations ===

gl4cts::ContextFlushControl::FunctionalTest::FunctionalTest(deqp::Context &context)
    : deqp::TestCase(context, "functional", "Context Flush Control Functional Test")
{
    /* Intentionally left blank. */
}

tcu::TestNode::IterateResult gl4cts::ContextFlushControl::FunctionalTest::iterate()
{
    /* Shortcut for GL functionality. */
    const glw::Functions &gl = m_context.getRenderContext().getFunctions();

    /* Get current platform.*/
    glu::Platform &platform = dynamic_cast<glu::Platform &>(m_context.getTestContext().getPlatform());

    /* OpenGL support query. */
    bool is_at_least_gl_44 = (glu::contextSupports(m_context.getRenderContext().getType(), glu::ApiType::core(4, 4)));
    bool is_khr_context_flush_control = m_context.getContextInfo().isExtensionSupported("GL_KHR_context_flush_control");

    /* Running tests. */
    bool is_ok    = true;
    bool is_error = false;

    /* This test should only be executed if we're running a GL4.4 context or related extension is available */
    try
    {
        if ((is_at_least_gl_44 || is_khr_context_flush_control) &&
            (nullptr != platform.getContextFlushControlContextAttributes()))
        {
            glw::GLfloat test_time_no_flush = testTime(false);
            glw::GLfloat test_time_flush    = testTime(true);

            is_ok = (test_time_no_flush < test_time_flush);
        }
        else
        {
            is_error = true;
        }
    }
    catch (...)
    {
        is_ok    = false;
        is_error = true;
    }

    /* Result's setup. */
    if (is_ok)
    {
        if (is_error)
        {
            m_context.getTestContext().getLog()
                << tcu::TestLog::Message << "The context does not support No-Flush behavior."
                << tcu::TestLog::EndMessage;

            m_testCtx.setTestResult(QP_TEST_RESULT_NOT_SUPPORTED, "Not supported.");
        }
        else
        {
            m_testCtx.setTestResult(QP_TEST_RESULT_PASS, "Pass");
        }
    }
    else
    {
        if (is_error)
        {
            m_context.getTestContext().getLog()
                << tcu::TestLog::Message << "Internal error has occured during Context Flush Control Functional test."
                << tcu::TestLog::EndMessage;

            m_testCtx.setTestResult(QP_TEST_RESULT_INTERNAL_ERROR, "Test error.");
        }
        else
        {
            m_context.getTestContext().getLog()
                << tcu::TestLog::Message
                << "The running time of no-flush context switches has been slower than flush "
                   "behavior context switching case. "
                << "This is not expected from quality implementation." << tcu::TestLog::EndMessage;

            m_testCtx.setTestResult(QP_TEST_RESULT_QUALITY_WARNING, "Quality warning.");
        }
    }

    return STOP;
}

glw::GLfloat gl4cts::ContextFlushControl::FunctionalTest::testTime(bool shall_flush_on_release)
{
    /* Create two contexts to be switched during test. */
    DrawSetup draw_context_setup[2] = {DrawSetup(m_context, shall_flush_on_release),
                                       DrawSetup(m_context, shall_flush_on_release)};

    /* Check starting time. */
    uint64_t start_time = deGetMicroseconds();

    /* Loop over draw-switch context. */
    for (glw::GLuint i = 0; i < 1024; ++i)
    {
        draw_context_setup[i % 2].makeCurrent();
        draw_context_setup[i % 2].draw();
    }

    /* Check end time. */
    uint64_t end_time = deGetMicroseconds();

    /* Return resulting run-time. */
    return (glw::GLfloat)(end_time - start_time);
}

