{
    const Functions &gl = m_context.getRenderContext().getFunctions();

    /* Clean textures and buffers. Errors ignored */
    gl.deleteTextures(1, &m_dst_tex_name);
    gl.deleteTextures(1, &m_src_tex_name);

    m_dst_tex_name = 0;
