    if (0 != m_dst_buf_name)
    {
        gl.deleteBuffers(1, &m_dst_buf_name);
        m_dst_buf_name = 0;
    }

    if (0 != m_src_buf_name)
    {
        gl.deleteBuffers(1, &m_src_buf_name);
        m_src_buf_name = 0;
    }
}

