        m_test_cases.push_back(test_case);

        test_case.m_dst_level = 0;
        test_case.m_src_level = 1;
        m_test_cases.push_back(test_case);

        test_case.m_dst_level = 1;
        test_case.m_src_level = 1;
        m_test_cases.push_back(test_case);
    }
