    if (GL_NO_ERROR == gl.getError())
    {
        for (glw::GLuint i = 0; i < sizeof(s_initial_data_b) / sizeof(s_initial_data_b[0]); ++i)
        {
            if (s_expected_data[i] != output_data[i])
            {
