        if (parameter_legacy != parameter_dsa)
        {
            m_context.getTestContext().getLog()
                << tcu::TestLog::Message << "GetNamedFramebufferParameteriv returned " << parameter_dsa << ", but "
                << parameter_legacy << " was expected for " << pnames_strings[i]
                << " parameter name of framebuffer object." << tcu::TestLog::EndMessage;

            is_ok = false;
        }
    }

    return is_ok;
}

void GetParametersTest::Clean()
{
    /* Shortcut for GL functionality. */
    const glw::Functions &gl = m_context.getRenderContext().getFunctions();

