                  not_matching_format, GL_UNSIGNED_BYTE, s_reference);
    GLU_EXPECT_NO_ERROR(gl.getError(), "glTexImage2D has failed");

    is_compressed = 0;

    gl.getTexLevelParameteriv(GL_TEXTURE_2D, 0, GL_TEXTURE_COMPRESSED, &is_compressed);
