    glw::GLuint not_a_bo  = 0;

    /* Valid setup. */
    glw::GLintptr valid_offset = 0;
    glw::GLsizei valid_stride  = 1;

    /* Limits. (Minimum values - OpenGL 4.5 Core Specification, Table 23.55) */
    glw::GLint max_vertex_attrib_bindings = 16;
