                                      "    tes_gs += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout (location = 1, component = COMPONENT) FLAT out TYPE gohan;\n"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_tcs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    gohan = TYPE(1);\n"
                                      "\n"
                                      "    vs_tcs = in_vs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 in_vs;\n"
