class XFBDuplicatedStrideTest : public NegativeTestBase
{
public:
    enum CASES
    {
        VALID = 0,
        INVALID,

        /* */
        CASE_MAX
    };

    /* Public methods */
    XFBDuplicatedStrideTest(deqp::Context &context, glw::GLuint constant, glw::GLuint stage);

    virtual ~XFBDuplicatedStrideTest()
    {
    }

protected:
    /* Methods to be implemented by child class */
    virtual std::string getShaderSource(glw::GLuint test_case_index, Utils::Shader::STAGES stage);

    virtual std::string getTestCaseName(glw::GLuint test_case_index);
    virtual glw::GLuint getTestCaseNumber();
    virtual bool isComputeRelevant(glw::GLuint test_case_index);
    virtual bool isFailureExpected(glw::GLuint test_case_index);
    virtual void testInit();
    std::string getCaseEnumName(glw::GLuint test_case_index);

private:
    /* Private types */
    struct testCase
    {
        CASES m_case;
        Utils::Shader::STAGES m_stage;
    };

    /* Private fields */
    std::vector<testCase> m_test_cases;
    glw::GLuint m_constant;
    glw::GLuint m_stage;
};



// === Member function implementations ===

XFBDuplicatedStrideTest::XFBDuplicatedStrideTest(deqp::Context &context, GLuint constant, GLuint stage)
    : NegativeTestBase(context, "xfb_duplicated_stride",
                       "Test verifies that compiler reports error when conflicting stride qualifiers are used")
    , m_constant(constant)
    , m_stage(stage)
{
    std::string name = ("xfb_duplicated_stride_");
    name.append(getCaseEnumName(m_constant));
    name.append("_");
    name.append(EnhancedLayouts::Utils::Shader::GetStageName((EnhancedLayouts::Utils::Shader::STAGES)stage));

    NegativeTestBase::m_name = name.c_str();
}

std::string XFBDuplicatedStrideTest::getShaderSource(GLuint test_case_index, Utils::Shader::STAGES stage)
{
    static const GLchar *invalid_var_definition = "const uint valid_stride = 64;\n"
#if DEBUG_NEG_REMOVE_ERROR
                                                  "const uint conflicting_stride = 64;\n"
#else
                                                  "const uint conflicting_stride = 128;\n"
#endif /* DEBUG_NEG_REMOVE_ERROR */
                                                  "\n"
                                                  "layout (xfb_buffer = 0, xfb_stride = valid_stride)       out;\n"
                                                  "layout (xfb_buffer = 0, xfb_stride = conflicting_stride) out;\n";
    static const GLchar *valid_var_definition = "const uint valid_stride = 64;\n"
                                                "\n"
                                                "layout (xfb_buffer = 0, xfb_stride = valid_stride) out;\n"
                                                "layout (xfb_buffer = 0, xfb_stride = valid_stride) out;\n";
    static const GLchar *fs                   = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "in  vec4 any_fs;\n"
                                                "out vec4 fs_out;\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "    fs_out = any_fs;\n"
                                                "}\n"
                                                "\n";
    static const GLchar *gs_tested            = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "layout(points)                           in;\n"
                                                "layout(triangle_strip, max_vertices = 4) out;\n"
                                                "\n"
                                                "VAR_DEFINITION"
                                                "\n"
                                                "in  vec4 vs_any[];\n"
                                                "out vec4 any_fs;\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "    vec4 result = vs_any[0];\n"
                                                "\n"
                                                "    any_fs = result;\n"
                                                "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                                "    EmitVertex();\n"
                                                "    any_fs = result;\n"
                                                "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                                "    EmitVertex();\n"
                                                "    any_fs = result;\n"
                                                "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                                "    EmitVertex();\n"
                                                "    any_fs = result;\n"
                                                "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                                "    EmitVertex();\n"
                                                "}\n"
                                                "\n";
    static const GLchar *tcs                  = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "layout(vertices = 1) out;\n"
                                                "\n"
                                                "in  vec4 vs_any[];\n"
                                                "out vec4 tcs_tes[];\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "\n"
                                                "    tcs_tes[gl_InvocationID] = vs_any[gl_InvocationID];\n"
                                                "\n"
                                                "    gl_TessLevelOuter[0] = 1.0;\n"
                                                "    gl_TessLevelOuter[1] = 1.0;\n"
                                                "    gl_TessLevelOuter[2] = 1.0;\n"
                                                "    gl_TessLevelOuter[3] = 1.0;\n"
                                                "    gl_TessLevelInner[0] = 1.0;\n"
                                                "    gl_TessLevelInner[1] = 1.0;\n"
                                                "}\n"
                                                "\n";
    static const GLchar *tes_tested           = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "layout(isolines, point_mode) in;\n"
                                                "\n"
                                                "VAR_DEFINITION"
                                                "\n"
                                                "in  vec4 tcs_tes[];\n"
                                                "out vec4 any_fs;\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "    vec4 result = tcs_tes[0];\n"
                                                "\n"
                                                "    any_fs = result;\n"
                                                "}\n"
                                                "\n";
    static const GLchar *vs                   = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "in  vec4 in_vs;\n"
                                                "out vec4 vs_any;\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "    vs_any = in_vs;\n"
                                                "}\n"
                                                "\n";
    static const GLchar *vs_tested            = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "VAR_DEFINITION"
                                                "\n"
                                                "in  vec4 in_vs;\n"
                                                "out vec4 any_fs;\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "    vec4 result = in_vs;\n"
                                                "\n"
                                                "    any_fs += result;\n"
                                                "}\n"
                                                "\n";

    std::string source;
    testCase &test_case = m_test_cases[test_case_index];

    if (test_case.m_stage == stage)
    {
        size_t position              = 0;
        const GLchar *var_definition = 0;

        switch (test_case.m_case)
        {
        case VALID:
            var_definition = valid_var_definition;
            break;
        case INVALID:
            var_definition = invalid_var_definition;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        switch (stage)
        {
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes_tested;
            break;
        case Utils::Shader::VERTEX:
            source = vs_tested;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        Utils::replaceToken("VAR_DEFINITION", position, var_definition, source);
    }
    else
    {
        switch (test_case.m_stage)
        {
        case Utils::Shader::GEOMETRY:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::TESS_EVAL:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::TESS_CTRL:
                source = tcs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::VERTEX:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            default:
                source = "";
            }
            break;
        default:
            TCU_FAIL("Invalid enum");
        }
    }

    return source;
}

std::string XFBDuplicatedStrideTest::getTestCaseName(GLuint test_case_index)
{
    std::stringstream stream;
    testCase &test_case = m_test_cases[test_case_index];

    stream << "Stage: " << Utils::Shader::GetStageName(test_case.m_stage) << ", case: ";

    switch (test_case.m_case)
    {
    case VALID:
        stream << "valid";
        break;
    case INVALID:
        stream << "invalid";
        break;
    default:
        TCU_FAIL("Invalid enum");
    }

    return stream.str();
}

std::string XFBDuplicatedStrideTest::getCaseEnumName(GLuint test_case_index)
{
    std::string name = "case_max";

    switch (test_case_index)
    {
    case 0:
        name = "valid";
        break;
    case 1:
        name = "invalid";
        break;
    default:
        name = "case_max";
        break;
    }

    return name;
}

GLuint XFBDuplicatedStrideTest::getTestCaseNumber()
{
    return static_cast<GLuint>(m_test_cases.size());
}

bool XFBDuplicatedStrideTest::isComputeRelevant(GLuint /* test_case_index */)
{
    return false;
}

bool XFBDuplicatedStrideTest::isFailureExpected(GLuint test_case_index)
{
    testCase &test_case = m_test_cases[test_case_index];

    return (INVALID == test_case.m_case);
}

void XFBDuplicatedStrideTest::testInit()
{
    testCase test_case = {(CASES)m_constant, (Utils::Shader::STAGES)m_stage};

    m_test_cases.push_back(test_case);
}

