        std::map<std::string, GLuint> indicesO;
        VerifyGetProgramResourceIndex(vs, GL_UNIFORM, indicesU, "u", error);
        VerifyGetProgramResourceIndex(vs, GL_UNIFORM, indicesU, "v", error);
