        case GL_MAX_VERTEX_ATOMIC_COUNTERS:
            return "GL_MAX_VERTEX_ATOMIC_COUNTERS";
        case GL_MAX_TESS_CONTROL_ATOMIC_COUNTERS:
            return "GL_MAX_TESS_CONTROL_ATOMIC_COUNTERS";
