        GLint i;
        glGetIntegerv(e, &i);
        if (i != expected)
        {
            ok = false;
            m_context.getTestContext().getLog()
                << tcu::TestLog::Message << GLenumToString(e) << " state is incorrect (GetIntegerv, is: " << i
                << ", expected: " << expected << ")" << tcu::TestLog::EndMessage;
