        {
            ok = false;
            m_context.getTestContext().getLog()
                << tcu::TestLog::Message
                << "GL_ATOMIC_COUNTER_BUFFER_BINDING state is incorrect (GetBooleani_v, is: " << d
                << ", expected: " << (binding ? GL_TRUE : GL_FALSE) << ", index: " << index << ")"
