                                                << " state is incorrect (GetInteger64v, is: " << static_cast<GLint>(i64)
                                                << ", expected: " << expected << ")" << tcu::TestLog::EndMessage;
        }

        GLfloat f;
        glGetFloatv(e, &f);
        if (f != static_cast<GLfloat>(expected))
