        glReadPixels(0, 0, width, height, GL_RGBA, GL_UNSIGNED_BYTE, &fb[0]);

        bool status = true;
        int bad     = 0;

        // left-bottom quad
        for (int y = 10, i = (100 * 10 + 10) * 4; y < height / 2 - 10; ++y, i += 70 * 4)
        {
            for (int x = 10; x < width / 2 - 10; ++x, i += 4)
