                << tcu::TestLog::EndMessage;
            //return status;
        }
        // left-top quad
        for (int y = height / 2 + 10, i = (100 * 60 + 10) * 4; y < height - 10; ++y, i += 70 * 4)
        {
            for (int x = 10; x < width / 2 - 10; ++x, i += 4)
            {
                const vec3 c = vec3(fb[i], fb[i + 1], fb[i + 2]);
