class FunctionalTest14_15 : public deqp::TestCase
{
public:
    FunctionalTest14_15(deqp::Context &context);

    virtual tcu::TestNode::IterateResult iterate();

private:
    /* Private methods */
    bool testDefaultSubroutineSet(const Utils::vec4<glw::GLuint> &uni_input,
