            << "Program interface: " << Utils::programInterfaceToStr(program_interface) << ". "
            << "Resource name: " << resource_name << ". "
            << "Property: " << Utils::pnameToStr(pname) << ". "
            << "Result: " << value << ". "
            << "Expected: " << expected << "." << tcu::TestLog::EndMessage;

        return false;
    }
    else
    {
        return true;
    }
}

