        result = "TEST_CASE_INVALID_LOCAL_SUBROUTINE_VARIABLE";
        break;
    case TEST_CASE_INVALID_GLOBAL_SUBROUTINE_VARIABLE:
        result = "TEST_CASE_INVALID_GLOBAL_SUBROUTINE_VARIABLE";
        break;
    case TEST_CASE_SUBROUTINE_USED_AS_CONSTRUCTOR:
