                              "Geometry shader:\n"
                              "\n"
                           << gs_body
                           << "\n"
                              "Fragment shader:\n"
                              "\n"
                           << fs_body << tcu::TestLog::EndMessage;

        m_has_test_passed = false;
    }
}

