    GLU_EXPECT_NO_ERROR(m_gl.getError(), "glGenVertexArrays() call failed.");

    m_gl.bindVertexArray(m_vao);
    GLU_EXPECT_NO_ERROR(m_gl.getError(), "glBindVertexArray() call failed.");

    return true;
}

