                               "}\n"
                               "\n";
    static const GLchar *fs  = "#version 430 core\n"
                               "#extension GL_ARB_enhanced_layouts : require\n"
                               "\n"
                               "in  vec4 gs_fs;\n"
                               "out vec4 fs_out;\n"
                               "\n"
                               "void main()\n"
                               "{\n"
                               "ASSIGNMENT"
                               "    fs_out = gs_fs;\n"
                               "}\n"
                               "\n";
    static const GLchar *gs  = "#version 430 core\n"
                               "#extension GL_ARB_enhanced_layouts : require\n"
                               "\n"
                               "layout(points)                           in;\n"
                               "layout(triangle_strip, max_vertices = 4) out;\n"
                               "\n"
                               "in  vec4 tes_gs[];\n"
                               "out vec4 gs_fs;\n"
                               "\n"
                               "void main()\n"
                               "{\n"
                               "ASSIGNMENT"
                               "    gs_fs = tes_gs[0];\n"
                               "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                               "    EmitVertex();\n"
                               "    gs_fs = tes_gs[0];\n"
                               "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                               "    EmitVertex();\n"
                               "    gs_fs = tes_gs[0];\n"
                               "    gl_Position  = vec4(1, -1, 0, 1);\n"
                               "    EmitVertex();\n"
                               "    gs_fs = tes_gs[0];\n"
                               "    gl_Position  = vec4(1, 1, 0, 1);\n"
                               "    EmitVertex();\n"
                               "}\n"
                               "\n";
    static const GLchar *tcs = "#version 430 core\n"
                               "#extension GL_ARB_enhanced_layouts : require\n"
                               "\n"
                               "layout(vertices = 1) out;\n"
                               "\n"
                               "in  vec4 vs_tcs[];\n"
                               "out vec4 tcs_tes[];\n"
                               "\n"
                               "void main()\n"
                               "{\n"
                               "\n"
                               "ASSIGNMENT"
                               "    tcs_tes[gl_InvocationID] = vs_tcs[gl_InvocationID];\n"
                               "\n"
                               "    gl_TessLevelOuter[0] = 1.0;\n"
                               "    gl_TessLevelOuter[1] = 1.0;\n"
                               "    gl_TessLevelOuter[2] = 1.0;\n"
                               "    gl_TessLevelOuter[3] = 1.0;\n"
                               "    gl_TessLevelInner[0] = 1.0;\n"
                               "    gl_TessLevelInner[1] = 1.0;\n"
                               "}\n"
                               "\n";
    static const GLchar *tes = "#version 430 core\n"
                               "#extension GL_ARB_enhanced_layouts : require\n"
                               "\n"
                               "layout(isolines, point_mode) in;\n"
                               "\n"
                               "in  vec4 tcs_tes[];\n"
                               "out vec4 tes_gs;\n"
                               "\n"
                               "void main()\n"
                               "{\n"
                               "ASSIGNMENT"
                               "    tes_gs = tcs_tes[0];\n"
                               "}\n"
                               "\n";
    static const GLchar *vs  = "#version 430 core\n"
                               "#extension GL_ARB_enhanced_layouts : require\n"
                               "\n"
                               "in  vec4 in_vs;\n"
                               "out vec4 vs_tcs;\n"
                               "\n"
                               "void main()\n"
                               "{\n"
                               "ASSIGNMENT"
                               "    vs_tcs = in_vs;\n"
                               "}\n"
                               "\n";

    std::string source;
    testCase &test_case = m_test_cases[test_case_index];

    if (Utils::Shader::COMPUTE == test_case.m_stage)
    {
        size_t position = 0;

        source = cs;

        Utils::replaceToken("CONSTANT", position, getConstantName(test_case.m_constant), source);
