                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 gs_fs;\n"
                                      "out vec4 fs_out;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = gs_fs;\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    fs_out += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *gs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(points)                           in;\n"
                                      "layout(triangle_strip, max_vertices = 4) out;\n"
                                      "\n"
                                      "in  vec4 tes_gs[];\n"
                                      "out vec4 gs_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "}\n"
                                      "\n";
    static const GLchar *gs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(points)                           in;\n"
                                      "layout(triangle_strip, max_vertices = 4) out;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 tes_gs[];\n"
                                      "out vec4 gs_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = tes_gs[0];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tcs        = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(vertices = 1) out;\n"
                                      "\n"
                                      "in  vec4 vs_tcs[];\n"
                                      "out vec4 tcs_tes[];\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "\n"
                                      "    tcs_tes[gl_InvocationID] = vs_tcs[gl_InvocationID];\n"
                                      "\n"
                                      "    gl_TessLevelOuter[0] = 1.0;\n"
                                      "    gl_TessLevelOuter[1] = 1.0;\n"
                                      "    gl_TessLevelOuter[2] = 1.0;\n"
                                      "    gl_TessLevelOuter[3] = 1.0;\n"
                                      "    gl_TessLevelInner[0] = 1.0;\n"
                                      "    gl_TessLevelInner[1] = 1.0;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tcs_tested = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(vertices = 1) out;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 vs_tcs[];\n"
                                      "out vec4 tcs_tes[];\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = vs_tcs[gl_InvocationID];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    tcs_tes[gl_InvocationID] = result;\n"
                                      "\n"
                                      "    gl_TessLevelOuter[0] = 1.0;\n"
                                      "    gl_TessLevelOuter[1] = 1.0;\n"
                                      "    gl_TessLevelOuter[2] = 1.0;\n"
                                      "    gl_TessLevelOuter[3] = 1.0;\n"
                                      "    gl_TessLevelInner[0] = 1.0;\n"
                                      "    gl_TessLevelInner[1] = 1.0;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tes        = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(isolines, point_mode) in;\n"
                                      "\n"
                                      "in  vec4 tcs_tes[];\n"
                                      "out vec4 tes_gs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    tes_gs = tcs_tes[0];\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tes_tested = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(isolines, point_mode) in;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 tcs_tes[];\n"
                                      "out vec4 tes_gs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = tcs_tes[0];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    tes_gs += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_tcs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vs_tcs = in_vs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_tcs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = in_vs;\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    vs_tcs += result;\n"
                                      "}\n"
                                      "\n";

    std::string source;
    testCase &test_case = m_test_cases[test_case_index];

    if (test_case.m_stage == stage)
    {
        const GLchar *array = "";
        GLchar buffer_gohan[16];
        GLchar buffer_goten[16];
        const GLchar *flat      = "";
        const GLchar *index     = "";
        size_t position         = 0;
        const GLchar *type_name = test_case.m_type.GetGLSLTypeName();

        if (isFlatRequired(stage, test_case.m_type, Utils::Variable::VARYING_OUTPUT))
        {
            flat = "flat";
        }

        sprintf(buffer_gohan, "%d", test_case.m_component_gohan);
        sprintf(buffer_goten, "%d", test_case.m_component_goten);

        switch (stage)
        {
        case Utils::Shader::FRAGMENT:
            source = fs_tested;
            break;
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            break;
        case Utils::Shader::TESS_CTRL:
            source = tcs_tested;
            array  = "[]";
            index  = "[gl_InvocationID]";
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes_tested;
            break;
        case Utils::Shader::VERTEX:
            source = vs_tested;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        Utils::replaceToken("VAR_DEFINITION", position, var_definition, source);
        position = 0;
        Utils::replaceToken("COMPONENT", position, buffer_gohan, source);
        Utils::replaceToken("FLAT", position, flat, source);
        Utils::replaceToken("ARRAY", position, array, source);
        Utils::replaceToken("COMPONENT", position, buffer_goten, source);
        Utils::replaceToken("FLAT", position, flat, source);
        Utils::replaceToken("ARRAY", position, array, source);
        Utils::replaceToken("VARIABLE_USE", position, l_test, source);

        Utils::replaceAllTokens("TYPE", type_name, source);
        Utils::replaceAllTokens("INDEX", index, source);
    }
    else
    {
        switch (stage)
        {
        case Utils::Shader::FRAGMENT:
            source = fs;
            break;
        case Utils::Shader::GEOMETRY:
            source = gs;
            break;
        case Utils::Shader::TESS_CTRL:
            source = tcs;
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes;
            break;
        case Utils::Shader::VERTEX:
            source = vs;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }
    }

    return source;
}

std::string OutputComponentAliasingTest::getTestCaseName(GLuint test_case_index)
{
    std::stringstream stream;
    testCase &test_case = m_test_cases[test_case_index];

    stream << "Stage: " << Utils::Shader::GetStageName(test_case.m_stage)
           << " type: " << test_case.m_type.GetGLSLTypeName() << ", components: " << test_case.m_component_gohan
           << " & " << test_case.m_component_goten;

    return stream.str();
}

GLuint OutputComponentAliasingTest::getTestCaseNumber()
{
    return static_cast<GLuint>(m_test_cases.size());
}

bool OutputComponentAliasingTest::isComputeRelevant(GLuint /* test_case_index */)
{
    return false;
}

void OutputComponentAliasingTest::testInit()
{
    const Utils::Type &type                     = getType(m_type);
    const std::vector<GLuint> &valid_components = type.GetValidComponents();

    for (std::vector<GLuint>::const_iterator it_gohan = valid_components.begin(); it_gohan != valid_components.end();
         ++it_gohan)
    {
        const GLuint max_component = *it_gohan + type.GetNumComponents();
        for (std::vector<GLuint>::const_iterator it_goten = it_gohan;
             it_goten != valid_components.end() && max_component > *it_goten; ++it_goten)
        {
            for (GLuint stage = 0; stage < Utils::Shader::STAGE_MAX; ++stage)
            {
                /* Skip compute shader */
                if (Utils::Shader::COMPUTE == stage)
                {
                    continue;
                }

                if ((Utils::Shader::FRAGMENT == stage) && (Utils::Type::Double == type.m_basic_type))
                {
                    continue;
                }

                testCase test_case = {*it_gohan, *it_goten, (Utils::Shader::STAGES)stage, type};

                m_test_cases.push_back(test_case);
            }
        }
    }
}

