class VaryingBlockAutomaticMemberLocationsTest : public NegativeTestBase
{
public:
    /* Public methods */
    VaryingBlockAutomaticMemberLocationsTest(deqp::Context &context, glw::GLuint stage);

    virtual ~VaryingBlockAutomaticMemberLocationsTest()
    {
    }

protected:
    /* Methods to be implemented by child class */
    virtual std::string getShaderSource(glw::GLuint test_case_index, Utils::Shader::STAGES stage);

    virtual std::string getTestCaseName(glw::GLuint test_case_index);
    virtual glw::GLuint getTestCaseNumber();
    virtual bool isComputeRelevant(glw::GLuint test_case_index);
    virtual void testInit();

private:
    /* Private types */
    struct testCase
    {
        bool m_is_input;
        Utils::Shader::STAGES m_stage;
    };

    /* Private fields */
    std::vector<testCase> m_test_cases;
    glw::GLuint m_stage;
};



// === Member function implementations ===

VaryingBlockAutomaticMemberLocationsTest::VaryingBlockAutomaticMemberLocationsTest(deqp::Context &context, GLuint stage)
    : NegativeTestBase(
          context, "varying_block_automatic_member_locations",
          "Test verifies that compiler assigns subsequent locations to block members, even if this causes errors")
    , m_stage(stage)
{
    std::string name = ("varying_block_automatic_member_locations_");
    name.append(EnhancedLayouts::Utils::Shader::GetStageName((EnhancedLayouts::Utils::Shader::STAGES)stage));

    NegativeTestBase::m_name = name.c_str();
}

std::string VaryingBlockAutomaticMemberLocationsTest::getShaderSource(GLuint test_case_index,
                                                                      Utils::Shader::STAGES stage)
{
    static const GLchar *block_definition = "layout (location = 2) DIRECTION DBZ {\n"
                                            "    vec4 goku;\n"
                                            "    vec4 gohan[4];\n"
                                            "    vec4 goten;\n"
#if DEBUG_NEG_REMOVE_ERROR
                                            "    /* layout (location = 1) */ vec4 chichi;\n"
#else
                                            "    layout (location = 1) vec4 chichi;\n"
#endif /* DEBUG_NEG_REMOVE_ERROR */
                                            "    vec4 pan;\n"
                                            "} dbzARRAY;\n";
    static const GLchar *input_use  = "    result += dbzINDEX.goku + dbzINDEX.gohan[0] + dbzINDEX.gohan[1] + "
                                      "dbzINDEX.gohan[3] + dbzINDEX.gohan[2] + dbzINDEX.goten + dbzINDEX.chichi + "
                                      "dbzINDEX.pan;\n";
    static const GLchar *output_use = "    dbzINDEX.goku     = result;\n"
                                      "    dbzINDEX.gohan[0] = result / 2;\n"
                                      "    dbzINDEX.gohan[1] = result / 2.25;\n"
                                      "    dbzINDEX.gohan[2] = result / 2.5;\n"
                                      "    dbzINDEX.gohan[3] = result / 2.75;\n"
                                      "    dbzINDEX.goten    = result / 4  - dbzINDEX.gohan[0] - dbzINDEX.gohan[1] - "
                                      "dbzINDEX.gohan[2] - dbzINDEX.gohan[3];\n"
                                      "    dbzINDEX.chichi   = result / 8  - dbzINDEX.goten;\n"
                                      "    dbzINDEX.pan      = result / 16 - dbzINDEX.chichi;\n";
    static const GLchar *fs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 gs_fs;\n"
                                      "out vec4 fs_out;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    fs_out = gs_fs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *fs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "BLOCK_DEFINITION"
                                      "\n"
                                      "in  vec4 gs_fs;\n"
                                      "out vec4 fs_out;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = gs_fs;\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    fs_out += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *gs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(points)                           in;\n"
                                      "layout(triangle_strip, max_vertices = 4) out;\n"
                                      "\n"
                                      "in  vec4 tes_gs[];\n"
                                      "out vec4 gs_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "}\n"
                                      "\n";
    static const GLchar *gs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(points)                           in;\n"
                                      "layout(triangle_strip, max_vertices = 4) out;\n"
                                      "\n"
                                      "BLOCK_DEFINITION"
                                      "\n"
                                      "in  vec4 tes_gs[];\n"
                                      "out vec4 gs_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = tes_gs[0];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tcs        = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(vertices = 1) out;\n"
                                      "\n"
                                      "in  vec4 vs_tcs[];\n"
                                      "out vec4 tcs_tes[];\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "\n"
                                      "    tcs_tes[gl_InvocationID] = vs_tcs[gl_InvocationID];\n"
                                      "\n"
                                      "    gl_TessLevelOuter[0] = 1.0;\n"
                                      "    gl_TessLevelOuter[1] = 1.0;\n"
                                      "    gl_TessLevelOuter[2] = 1.0;\n"
                                      "    gl_TessLevelOuter[3] = 1.0;\n"
                                      "    gl_TessLevelInner[0] = 1.0;\n"
                                      "    gl_TessLevelInner[1] = 1.0;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tcs_tested = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(vertices = 1) out;\n"
                                      "\n"
                                      "BLOCK_DEFINITION"
                                      "\n"
                                      "in  vec4 vs_tcs[];\n"
                                      "out vec4 tcs_tes[];\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = vs_tcs[gl_InvocationID];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    tcs_tes[gl_InvocationID] = result;\n"
                                      "\n"
                                      "    gl_TessLevelOuter[0] = 1.0;\n"
                                      "    gl_TessLevelOuter[1] = 1.0;\n"
                                      "    gl_TessLevelOuter[2] = 1.0;\n"
                                      "    gl_TessLevelOuter[3] = 1.0;\n"
                                      "    gl_TessLevelInner[0] = 1.0;\n"
                                      "    gl_TessLevelInner[1] = 1.0;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tes        = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(isolines, point_mode) in;\n"
                                      "\n"
                                      "in  vec4 tcs_tes[];\n"
                                      "out vec4 tes_gs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    tes_gs = tcs_tes[0];\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tes_tested = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(isolines, point_mode) in;\n"
                                      "\n"
                                      "BLOCK_DEFINITION"
                                      "\n"
                                      "in  vec4 tcs_tes[];\n"
                                      "out vec4 tes_gs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = tcs_tes[0];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    tes_gs += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_tcs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vs_tcs = in_vs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "BLOCK_DEFINITION"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_tcs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = in_vs;\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    vs_tcs += result;\n"
                                      "}\n"
                                      "\n";

    const GLchar *array     = "";
    const GLchar *direction = "in";
    const GLchar *index     = "";
    std::string source;
    testCase &test_case   = m_test_cases[test_case_index];
    const GLchar *var_use = Utils::Shader::VERTEX == test_case.m_stage ? input_use : "\n";

    if (!test_case.m_is_input)
    {
        direction = "out";
        var_use   = output_use;
    }

    bool needs_vertex_output =
        stage == Utils::Shader::VERTEX && true == test_case.m_is_input && test_case.m_stage != Utils::Shader::VERTEX;
    bool needs_fragment_input = stage == Utils::Shader::FRAGMENT && false == test_case.m_is_input &&
                                test_case.m_stage != Utils::Shader::FRAGMENT;

    if (test_case.m_stage == stage || needs_vertex_output || needs_fragment_input)
    {
        size_t position = 0;

        switch (stage)
        {
        case Utils::Shader::FRAGMENT:
            direction = "in";
            var_use   = input_use;
            source    = fs_tested;
            break;
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            array  = test_case.m_is_input ? "[]" : "";
            index  = test_case.m_is_input ? "[0]" : "";
            break;
        case Utils::Shader::TESS_CTRL:
            source = tcs_tested;
            array  = "[]";
            index  = "[gl_InvocationID]";
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes_tested;
            array  = test_case.m_is_input ? "[]" : "";
            index  = test_case.m_is_input ? "[0]" : "";
            break;
        case Utils::Shader::VERTEX:
            direction = "out";
            var_use   = output_use;
            source    = vs_tested;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        Utils::replaceToken("BLOCK_DEFINITION", position, block_definition, source);
        position = 0;
        Utils::replaceToken("DIRECTION", position, direction, source);
        Utils::replaceToken("ARRAY", position, array, source);
        Utils::replaceToken("VARIABLE_USE", position, var_use, source);

        Utils::replaceAllTokens("INDEX", index, source);
    }
    else
    {
        switch (stage)
        {
        case Utils::Shader::FRAGMENT:
            source = fs;
            break;
        case Utils::Shader::GEOMETRY:
            source = gs;
            break;
        case Utils::Shader::TESS_CTRL:
            source = tcs;
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes;
            break;
        case Utils::Shader::VERTEX:
            source = vs;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }
    }

    return source;
}

std::string VaryingBlockAutomaticMemberLocationsTest::getTestCaseName(GLuint test_case_index)
{
    std::stringstream stream;
    testCase &test_case = m_test_cases[test_case_index];

    stream << "Stage: " << Utils::Shader::GetStageName(test_case.m_stage) << ", direction: ";

    if (true == test_case.m_is_input)
    {
        stream << "input";
    }
    else
    {
        stream << "output";
    }

    return stream.str();
}

GLuint VaryingBlockAutomaticMemberLocationsTest::getTestCaseNumber()
{
    return static_cast<GLuint>(m_test_cases.size());
}

bool VaryingBlockAutomaticMemberLocationsTest::isComputeRelevant(GLuint /* test_case_index */)
{
    return false;
}

void VaryingBlockAutomaticMemberLocationsTest::testInit()
{
    testCase test_case_in  = {true, (Utils::Shader::STAGES)m_stage};
    testCase test_case_out = {false, (Utils::Shader::STAGES)m_stage};

    if (Utils::Shader::VERTEX != m_stage)
    {
        m_test_cases.push_back(test_case_in);
    }

    if (Utils::Shader::FRAGMENT != m_stage)
    {
        m_test_cases.push_back(test_case_out);
    }
}

