        }
        catch (Utils::Shader::InvalidSourceException &exc)
        {
            if (false == is_failure_expected)
            {
                m_context.getTestContext().getLog()
                    << tcu::TestLog::Message << "Unexpected error in shader compilation: " << tcu::TestLog::EndMessage;
