    virtual std::string getTestCaseName(glw::GLuint test_case_index);
    virtual glw::GLuint getTestCaseNumber();
    virtual bool isComputeRelevant(glw::GLuint test_case_index);
    virtual void testInit();

private:
    /* Private types */
    struct testCase
    {
        Utils::Shader::STAGES m_stage;
    };

    /* Private fields */
    std::vector<testCase> m_test_cases;
    glw::GLuint m_stage;
};



// === Member function implementations ===

XFBBlockMemberBufferTest::XFBBlockMemberBufferTest(deqp::Context &context, GLuint stage)
    : NegativeTestBase(
          context, "xfb_block_member_buffer",
          "Test verifies that compiler reports error when block member has different xfb_buffer qualifier than buffer")
    , m_stage(stage)
{
    std::string name = ("xfb_block_member_buffer_");
    name.append(EnhancedLayouts::Utils::Shader::GetStageName((EnhancedLayouts::Utils::Shader::STAGES)stage));

    NegativeTestBase::m_name = name.c_str();
}

std::string XFBBlockMemberBufferTest::getShaderSource(GLuint test_case_index, Utils::Shader::STAGES stage)
{
    static const GLchar *var_definition = "layout (xfb_offset = 0) out Goku {\n"
                                          "                            vec4 gohan;\n"
#if DEBUG_NEG_REMOVE_ERROR
                                          "    /* layout (xfb_buffer = 1) */ vec4 goten;\n"
#else
                                          "    layout (xfb_buffer = 1) vec4 goten;\n"
#endif /* DEBUG_NEG_REMOVE_ERROR */
                                          "} goku;\n";
    static const GLchar *var_use    = "    goku.gohan = result / 2;\n"
                                      "    goku.goten = result / 4;\n";
    static const GLchar *fs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 any_fs;\n"
                                      "out vec4 fs_out;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    fs_out = any_fs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *gs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(points)                           in;\n"
                                      "layout(triangle_strip, max_vertices = 4) out;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 vs_any[];\n"
                                      "out vec4 any_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = vs_any[0];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    any_fs = result;\n"
                                      "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    any_fs = result;\n"
                                      "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    any_fs = result;\n"
                                      "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    any_fs = result;\n"
                                      "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tcs        = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(vertices = 1) out;\n"
                                      "\n"
                                      "in  vec4 vs_any[];\n"
                                      "out vec4 tcs_tes[];\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "\n"
                                      "    tcs_tes[gl_InvocationID] = vs_any[gl_InvocationID];\n"
                                      "\n"
                                      "    gl_TessLevelOuter[0] = 1.0;\n"
                                      "    gl_TessLevelOuter[1] = 1.0;\n"
                                      "    gl_TessLevelOuter[2] = 1.0;\n"
                                      "    gl_TessLevelOuter[3] = 1.0;\n"
                                      "    gl_TessLevelInner[0] = 1.0;\n"
                                      "    gl_TessLevelInner[1] = 1.0;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tes_tested = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(isolines, point_mode) in;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 tcs_tes[];\n"
                                      "out vec4 any_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = tcs_tes[0];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    any_fs += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_any;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vs_any = in_vs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 any_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = in_vs;\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    any_fs = result;\n"
                                      "}\n"
                                      "\n";

    std::string source;
    testCase &test_case = m_test_cases[test_case_index];

    if (test_case.m_stage == stage)
    {
        size_t position = 0;

        switch (stage)
        {
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes_tested;
            break;
        case Utils::Shader::VERTEX:
            source = vs_tested;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        Utils::replaceToken("VAR_DEFINITION", position, var_definition, source);
        position = 0;
        Utils::replaceToken("VARIABLE_USE", position, var_use, source);
    }
    else
    {
        switch (test_case.m_stage)
        {
        case Utils::Shader::GEOMETRY:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::TESS_EVAL:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::TESS_CTRL:
                source = tcs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::VERTEX:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            default:
                source = "";
            }
            break;
        default:
            TCU_FAIL("Invalid enum");
        }
    }

    return source;
}

std::string XFBBlockMemberBufferTest::getTestCaseName(GLuint test_case_index)
{
    std::stringstream stream;
    testCase &test_case = m_test_cases[test_case_index];

    stream << "Stage: " << Utils::Shader::GetStageName(test_case.m_stage);

    return stream.str();
}

GLuint XFBBlockMemberBufferTest::getTestCaseNumber()
{
    return static_cast<GLuint>(m_test_cases.size());
}

bool XFBBlockMemberBufferTest::isComputeRelevant(GLuint /* test_case_index */)
{
    return false;
}

void XFBBlockMemberBufferTest::testInit()
{
    testCase test_case = {(Utils::Shader::STAGES)m_stage};

    m_test_cases.push_back(test_case);
}

