                    << tcu::TestLog::EndMessage;
                exc.log(m_context);
            }

#endif /* DEBUG_NEG_LOG_ERROR */

            is_build_error = true;
        }
        catch (Utils::Program::BuildException &exc)
        {
            if (false == is_failure_expected)
