            is_build_error = true;
        }

        if (is_build_error != is_failure_expected)
        {
            if (!is_build_error)
            {
                m_context.getTestContext().getLog()
                    << tcu::TestLog::Message << "Unexpected success: " << tcu::TestLog::EndMessage;
