                                      "VARIABLE_USE"
                                      "\n"
                                      "    any_fs += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_any;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vs_any = in_vs;\n"
