        case BLOCK:
            var_definition = block_var_definition;
            var_use        = block_use;
            break;
        case GLOBAL:
            var_definition = global_var_definition;
            var_use        = global_use;
            break;
        case VECTOR:
            var_definition = vector_var_definition;
            var_use        = vector_use;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        switch (stage)
        {
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes_tested;
            break;
        case Utils::Shader::VERTEX:
            source = vs_tested;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        Utils::replaceToken("VAR_DEFINITION", position, var_definition, source);
        position = 0;
        Utils::replaceToken("MAX_BUFFER", position, buffer, source);
        Utils::replaceToken("VARIABLE_USE", position, var_use, source);
    }
    else
    {
        switch (test_case.m_stage)
        {
        case Utils::Shader::GEOMETRY:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::TESS_EVAL:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::TESS_CTRL:
                source = tcs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::VERTEX:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            default:
                source = "";
            }
            break;
        default:
            TCU_FAIL("Invalid enum");
        }
    }

    return source;
}

