    static const GLchar *offset_var_definition = "layout (xfb_offset = 16) in vec4 gohanARRAY;\n";
    static const GLchar *stride_var_definition = "layout (xfb_stride = 32) in vec4 gohanARRAY;\n";
#endif /* DEBUG_NEG_REMOVE_ERROR */
    static const GLchar *fs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 gs_fs;\n"
                                      "out vec4 fs_out;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    fs_out = gs_fs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *fs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 gs_fs;\n"
                                      "out vec4 fs_out;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = gs_fs;\n"
                                      "\n"
                                      "    fs_out = result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *gs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(points)                           in;\n"
                                      "layout(triangle_strip, max_vertices = 4) out;\n"
                                      "\n"
                                      "in  vec4 tes_gs[];\n"
                                      "out vec4 gs_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = tes_gs[0];\n"
                                      "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "}\n"
                                      "\n";
    static const GLchar *gs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(points)                           in;\n"
                                      "layout(triangle_strip, max_vertices = 4) out;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 tes_gs[];\n"
                                      "out vec4 gs_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = tes_gs[0];\n"
                                      "\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    gs_fs = result;\n"
                                      "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tcs        = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(vertices = 1) out;\n"
                                      "\n"
                                      "in  vec4 vs_tcs[];\n"
                                      "out vec4 tcs_tes[];\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "\n"
                                      "    tcs_tes[gl_InvocationID] = vs_tcs[gl_InvocationID];\n"
                                      "\n"
                                      "    gl_TessLevelOuter[0] = 1.0;\n"
                                      "    gl_TessLevelOuter[1] = 1.0;\n"
                                      "    gl_TessLevelOuter[2] = 1.0;\n"
                                      "    gl_TessLevelOuter[3] = 1.0;\n"
                                      "    gl_TessLevelInner[0] = 1.0;\n"
                                      "    gl_TessLevelInner[1] = 1.0;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tcs_tested = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(vertices = 1) out;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 vs_tcs[];\n"
                                      "out vec4 tcs_tes[];\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = vs_tcs[gl_InvocationID];\n"
                                      "\n"
                                      "    tcs_tes[gl_InvocationID] = result;\n"
                                      "\n"
                                      "    gl_TessLevelOuter[0] = 1.0;\n"
                                      "    gl_TessLevelOuter[1] = 1.0;\n"
                                      "    gl_TessLevelOuter[2] = 1.0;\n"
                                      "    gl_TessLevelOuter[3] = 1.0;\n"
                                      "    gl_TessLevelInner[0] = 1.0;\n"
                                      "    gl_TessLevelInner[1] = 1.0;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tes        = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(isolines, point_mode) in;\n"
                                      "\n"
                                      "in  vec4 tcs_tes[];\n"
                                      "out vec4 tes_gs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    tes_gs = tcs_tes[0];\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tes_tested = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(isolines, point_mode) in;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 tcs_tes[];\n"
                                      "out vec4 tes_gs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = tcs_tes[0];\n"
                                      "\n"
                                      "    tes_gs += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_tcs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vs_tcs = in_vs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
