                                      "out vec4 vs_tcs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = in_vs;\n"
                                      "\n"
                                      "    vs_tcs += result;\n"
                                      "}\n"
                                      "\n";

    std::string source;
    testCase &test_case = m_test_cases[test_case_index];

    if (test_case.m_stage == stage)
    {
        const GLchar *array          = "";
        size_t position              = 0;
        const GLchar *var_definition = 0;

        switch (test_case.m_qualifier)
        {
        case BUFFER:
            var_definition = buffer_var_definition;
            break;
        case OFFSET:
            var_definition = offset_var_definition;
            break;
        case STRIDE:
            var_definition = stride_var_definition;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        switch (stage)
        {
        case Utils::Shader::FRAGMENT:
            source = fs_tested;
            break;
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            array  = "[]";
            break;
        case Utils::Shader::TESS_CTRL:
            source = tcs_tested;
            array  = "[]";
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes_tested;
            array  = "[]";
            break;
        case Utils::Shader::VERTEX:
            source = vs_tested;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        Utils::replaceToken("VAR_DEFINITION", position, var_definition, source);
        position = 0;
        Utils::replaceToken("ARRAY", position, array, source);
    }
    else
    {
        switch (stage)
        {
        case Utils::Shader::FRAGMENT:
            source = fs;
            break;
        case Utils::Shader::GEOMETRY:
            source = gs;
            break;
        case Utils::Shader::TESS_CTRL:
            source = tcs;
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes;
            break;
        case Utils::Shader::VERTEX:
            source = vs;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }
    }

    return source;
}

std::string XFBInputTest::getTestCaseName(GLuint test_case_index)
{
    std::stringstream stream;
    testCase &test_case = m_test_cases[test_case_index];

    stream << "Stage: " << Utils::Shader::GetStageName(test_case.m_stage) << ", qualifier: ";

    switch (test_case.m_qualifier)
    {
    case BUFFER:
        stream << "xfb_buffer";
        break;
    case OFFSET:
        stream << "xfb_offset";
        break;
    case STRIDE:
        stream << "xfb_stride";
        break;
    default:
        TCU_FAIL("Invalid enum");
    }

    return stream.str();
}

