                                   "#extension GL_ARB_enhanced_layouts : require\n"
                                   "\n"
                                   "layout(points)                           in;\n"
                                   "layout(triangle_strip, max_vertices = 4) out;\n"
                                   "\n"
                                   "VAR_DEFINITION"
                                   "\n"
                                   "in  vec4 vs_gs[];\n"
                                   "out vec4 gs_fs;\n"
                                   "\n"
                                   "void main()\n"
                                   "{\n"
                                   "    vec4 result = vs_gs[0];\n"
                                   "\n"
                                   "VARIABLE_USE"
                                   "\n"
                                   "    gs_fs = result;\n"
                                   "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                   "    EmitVertex();\n"
                                   "    gs_fs = result;\n"
                                   "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                   "    EmitVertex();\n"
                                   "    gs_fs = result;\n"
                                   "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                   "    EmitVertex();\n"
                                   "    gs_fs = result;\n"
                                   "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                   "    EmitVertex();\n"
                                   "}\n"
                                   "\n";
    static const GLchar *vs      = "#version 430 core\n"
                                   "#extension GL_ARB_enhanced_layouts : require\n"
                                   "\n"
                                   "in  vec4 in_vs;\n"
                                   "out vec4 vs_gs;\n"
                                   "\n"
                                   "void main()\n"
                                   "{\n"
                                   "    vs_gs = in_vs;\n"
                                   "}\n"
                                   "\n";

    std::string source;

    if (Utils::Shader::GEOMETRY == stage)
    {
        size_t position = 0;

        source = gs;

        Utils::replaceToken("VAR_DEFINITION", position, var_definition, source);
        Utils::replaceToken("VARIABLE_USE", position, var_use, source);
    }
    else
    {
        switch (stage)
        {
        case Utils::Shader::FRAGMENT:
            source = fs;
            break;
        case Utils::Shader::VERTEX:
            source = vs;
            break;
        default:
            source = "";
        }
    }

    return source;
}

