class XFBOutputOverlappingTest : public NegativeTestBase
{
public:
    /* Public methods */
    XFBOutputOverlappingTest(deqp::Context &context, glw::GLuint type, glw::GLuint stage);

    virtual ~XFBOutputOverlappingTest()
    {
    }

    inline Utils::Type getTypeHelper(glw::GLuint index) const
    {
        return getType(index);
    }

protected:
    /* Methods to be implemented by child class */
    virtual std::string getShaderSource(glw::GLuint test_case_index, Utils::Shader::STAGES stage);

    virtual std::string getTestCaseName(glw::GLuint test_case_index);
    virtual glw::GLuint getTestCaseNumber();
    virtual bool isComputeRelevant(glw::GLuint test_case_index);
    virtual void testInit();

private:
    /* Private types */
    struct testCase
    {
        glw::GLuint m_offset;
        Utils::Shader::STAGES m_stage;
        Utils::Type m_type;
    };

    /* Private fields */
    std::vector<testCase> m_test_cases;
    glw::GLuint m_type;
    glw::GLuint m_stage;
};



// === Member function implementations ===

XFBOutputOverlappingTest::XFBOutputOverlappingTest(deqp::Context &context, GLuint type, GLuint stage)
    : NegativeTestBase(context, "xfb_output_overlapping",
                       "Test verifies that compiler reports error when two xfb qualified outputs overlap")
    , m_type(type)
    , m_stage(stage)
{
    std::string name = ("xfb_output_overlapping_");
    name.append(getTypeName(type));
    name.append("_");
    name.append(EnhancedLayouts::Utils::Shader::GetStageName((EnhancedLayouts::Utils::Shader::STAGES)stage));

    NegativeTestBase::m_name = name.c_str();
}

std::string XFBOutputOverlappingTest::getShaderSource(GLuint test_case_index, Utils::Shader::STAGES stage)
{
    static const GLchar *var_definition = "layout (xfb_offset = 0) out TYPE gohan;\n"
#if DEBUG_NEG_REMOVE_ERROR
                                          "/* layout (xfb_offset = OFFSET) */ out TYPE goten;\n";
#else
                                          "layout (xfb_offset = OFFSET) out TYPE goten;\n";
#endif /* DEBUG_NEG_REMOVE_ERROR */
    static const GLchar *var_use    = "    gohan = TYPE(0);\n"
                                      "    goten = TYPE(1);\n"
                                      "    if (vec4(0) == result)\n"
                                      "    {\n"
                                      "        gohan = TYPE(1);\n"
                                      "        goten = TYPE(0);\n"
                                      "    }\n";
    static const GLchar *fs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 any_fs;\n"
                                      "out vec4 fs_out;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    fs_out = any_fs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *gs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(points)                           in;\n"
                                      "layout(triangle_strip, max_vertices = 4) out;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 vs_any[];\n"
                                      "out vec4 any_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = vs_any[0];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    any_fs = result;\n"
                                      "    gl_Position  = vec4(-1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    any_fs = result;\n"
                                      "    gl_Position  = vec4(-1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    any_fs = result;\n"
                                      "    gl_Position  = vec4(1, -1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "    any_fs = result;\n"
                                      "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                      "    EmitVertex();\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tcs        = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(vertices = 1) out;\n"
                                      "\n"
                                      "in  vec4 vs_any[];\n"
                                      "out vec4 tcs_tes[];\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "\n"
                                      "    tcs_tes[gl_InvocationID] = vs_any[gl_InvocationID];\n"
                                      "\n"
                                      "    gl_TessLevelOuter[0] = 1.0;\n"
                                      "    gl_TessLevelOuter[1] = 1.0;\n"
                                      "    gl_TessLevelOuter[2] = 1.0;\n"
                                      "    gl_TessLevelOuter[3] = 1.0;\n"
                                      "    gl_TessLevelInner[0] = 1.0;\n"
                                      "    gl_TessLevelInner[1] = 1.0;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *tes_tested = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "layout(isolines, point_mode) in;\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 tcs_tes[];\n"
                                      "out vec4 any_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = tcs_tes[0];\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    any_fs += result;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs         = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 vs_any;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vs_any = in_vs;\n"
                                      "}\n"
                                      "\n";
    static const GLchar *vs_tested  = "#version 430 core\n"
                                      "#extension GL_ARB_enhanced_layouts : require\n"
                                      "\n"
                                      "VAR_DEFINITION"
                                      "\n"
                                      "in  vec4 in_vs;\n"
                                      "out vec4 any_fs;\n"
                                      "\n"
                                      "void main()\n"
                                      "{\n"
                                      "    vec4 result = in_vs;\n"
                                      "\n"
                                      "VARIABLE_USE"
                                      "\n"
                                      "    any_fs = result;\n"
                                      "}\n"
                                      "\n";

    std::string source;
    testCase &test_case = m_test_cases[test_case_index];

    if (test_case.m_stage == stage)
    {
        GLchar offset[16];
        size_t position         = 0;
        const GLchar *type_name = test_case.m_type.GetGLSLTypeName();

        sprintf(offset, "%d", test_case.m_offset);

        switch (stage)
        {
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes_tested;
            break;
        case Utils::Shader::VERTEX:
            source = vs_tested;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        Utils::replaceToken("VAR_DEFINITION", position, var_definition, source);
        position = 0;
        Utils::replaceToken("OFFSET", position, offset, source);
        Utils::replaceToken("VARIABLE_USE", position, var_use, source);

        Utils::replaceAllTokens("TYPE", type_name, source);
    }
    else
    {
        switch (test_case.m_stage)
        {
        case Utils::Shader::GEOMETRY:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::TESS_EVAL:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::TESS_CTRL:
                source = tcs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::VERTEX:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            default:
                source = "";
            }
            break;
        default:
            TCU_FAIL("Invalid enum");
        }
    }

    return source;
}

std::string XFBOutputOverlappingTest::getTestCaseName(GLuint test_case_index)
{
    std::stringstream stream;
    testCase &test_case = m_test_cases[test_case_index];

    stream << "Stage: " << Utils::Shader::GetStageName(test_case.m_stage)
           << ", type: " << test_case.m_type.GetGLSLTypeName() << ", offset: " << test_case.m_offset;

    return stream.str();
}

GLuint XFBOutputOverlappingTest::getTestCaseNumber()
{
    return static_cast<GLuint>(m_test_cases.size());
}

bool XFBOutputOverlappingTest::isComputeRelevant(GLuint /* test_case_index */)
{
    return false;
}

void XFBOutputOverlappingTest::testInit()
{
    const Utils::Type &type      = getType(m_type);
    const GLuint basic_type_size = Utils::Type::GetTypeSize(type.m_basic_type);

    /* Skip scalars, not applicable as:
     *
     *     The offset must be a multiple of the size of the first component of the first
     *     qualified variable or block member, or a compile-time error results.
     */

    testCase test_case = {basic_type_size /* offset */, (Utils::Shader::STAGES)m_stage, type};

    m_test_cases.push_back(test_case);
}

