        m_context.getTestContext().getLog()
            << tcu::TestLog::Message << "Queried value of pname " << glu::getTextureParameterStr(pname)
            << " is equal to " << value_dst << ", however " << value_ref << " was expected. Test fails."
            << tcu::TestLog::EndMessage;

        return false;
    }

    return true;
}

