class NegativeTestBase : public TestBase
{
public:
    /* Public methods */
    NegativeTestBase(deqp::Context &context, const glw::GLchar *test_name, const glw::GLchar *test_description);

    virtual ~NegativeTestBase()
    {
    }

protected:
