                                                "    EmitVertex();\n"
                                                "    any_fs = result;\n"
                                                "    gl_Position  = vec4(1, 1, 0, 1);\n"
                                                "    EmitVertex();\n"
                                                "}\n"
                                                "\n";
    static const GLchar *tcs                  = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "layout(vertices = 1) out;\n"
                                                "\n"
                                                "in  vec4 vs_any[];\n"
                                                "out vec4 tcs_tes[];\n"
                                                "\n"
                                                "void main()\n"
