                                                "}\n"
                                                "\n";
    static const GLchar *tes_tested           = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "layout(isolines, point_mode) in;\n"
                                                "\n"
                                                "VAR_DEFINITION"
                                                "\n"
                                                "in  vec4 tcs_tes[];\n"
                                                "out vec4 any_fs;\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "    vec4 result = tcs_tes[0];\n"
                                                "\n"
                                                "VARIABLE_USE"
                                                "\n"
                                                "    any_fs = result;\n"
                                                "}\n"
                                                "\n";
    static const GLchar *vs                   = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "in  vec4 in_vs;\n"
                                                "out vec4 vs_any;\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "    vs_any = in_vs;\n"
                                                "}\n"
                                                "\n";
    static const GLchar *vs_tested            = "#version 430 core\n"
                                                "#extension GL_ARB_enhanced_layouts : require\n"
                                                "\n"
                                                "VAR_DEFINITION"
                                                "\n"
                                                "in  vec4 in_vs;\n"
                                                "out vec4 any_fs;\n"
                                                "\n"
                                                "void main()\n"
                                                "{\n"
                                                "    vec4 result = in_vs;\n"
                                                "\n"
                                                "VARIABLE_USE"
                                                "\n"
                                                "    any_fs = result;\n"
                                                "}\n"
                                                "\n";

    std::string source;
    testCase &test_case = m_test_cases[test_case_index];

    if (test_case.m_stage == stage)
    {
        GLchar buffer[16];
        size_t position              = 0;
        const GLchar *type_name      = test_case.m_type.GetGLSLTypeName();
        const GLchar *var_definition = 0;
        const GLchar *var_use        = 0;

        sprintf(buffer, "%d", test_case.m_type.GetSize());

        switch (test_case.m_case)
        {
        case VALID:
            var_definition = valid_var_definition;
            var_use        = valid_use;
            break;
        case INVALID:
            var_definition = invalid_var_definition;
            var_use        = invalid_use;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        switch (stage)
        {
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            break;
        case Utils::Shader::TESS_EVAL:
            source = tes_tested;
            break;
        case Utils::Shader::VERTEX:
            source = vs_tested;
            break;
        default:
            TCU_FAIL("Invalid enum");
        }

        Utils::replaceToken("VAR_DEFINITION", position, var_definition, source);
        position = 0;
        Utils::replaceToken("SIZE", position, buffer, source);
        Utils::replaceToken("VARIABLE_USE", position, var_use, source);

        Utils::replaceAllTokens("TYPE", type_name, source);
    }
    else
    {
        switch (test_case.m_stage)
        {
        case Utils::Shader::GEOMETRY:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::TESS_EVAL:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            case Utils::Shader::TESS_CTRL:
                source = tcs;
                break;
            case Utils::Shader::VERTEX:
                source = vs;
                break;
            default:
                source = "";
            }
            break;
        case Utils::Shader::VERTEX:
            switch (stage)
            {
            case Utils::Shader::FRAGMENT:
                source = fs;
                break;
            default:
                source = "";
            }
            break;
        default:
            TCU_FAIL("Invalid enum");
        }
    }

    return source;
}

std::string XFBVariableStrideTest::getTestCaseName(GLuint test_case_index)
{
    std::stringstream stream;
    testCase &test_case = m_test_cases[test_case_index];

    stream << "Stage: " << Utils::Shader::GetStageName(test_case.m_stage)
           << ", type: " << test_case.m_type.GetGLSLTypeName() << ", case: ";

    switch (test_case.m_case)
    {
    case VALID:
        stream << "valid";
        break;
    case INVALID:
        stream << "invalid";
        break;
    default:
        TCU_FAIL("Invalid enum");
    }

    return stream.str();
}

std::string XFBVariableStrideTest::getCaseEnumName(glw::GLuint case_index)
{
    std::string case_name("case_max");
    switch (case_index)
    {
    case 0:
        case_name = "valid";
        break;
    case 1:
        case_name = "invalid";
        break;
    default:
        case_name = "case_max";
        break;
