                                          "        gokuINDEX.goten  = vec4(1, 1, 0, 1);\n"
                                          "        gokuINDEX.chichi = vec4(1, 0, 1, 1);\n"
                                          "    }\n";
    static const GLchar *gs_tested =
        "#version 430 core\n"
        "#extension GL_ARB_enhanced_layouts : require\n"
        "\n"
        "layout(points)                           in;\n"
        "layout(triangle_strip, max_vertices = 4) out;\n"
        "\n"
        "VAR_DEFINITION"
        "\n"
        "out gl_PerVertex \n"
        "{ \n"
        "   vec4  gl_Position; \n" // gl_Position must be redeclared in separable program mode
        "}; \n"
        "in  vec4 tes_gs[];\n"
        "out vec4 gs_fs;\n"
        "\n"
        "void main()\n"
        "{\n"
        "    vec4 result = tes_gs[0];\n"
        "\n"
        "VARIABLE_USE"
        "\n"
        "    gs_fs = result;\n"
        "    gl_Position  = vec4(-1, -1, 0, 1);\n"
        "    EmitVertex();\n"
        "    gs_fs = result;\n"
        "    gl_Position  = vec4(-1, 1, 0, 1);\n"
        "    EmitVertex();\n"
        "    gs_fs = result;\n"
        "    gl_Position  = vec4(1, -1, 0, 1);\n"
        "    EmitVertex();\n"
        "    gs_fs = result;\n"
        "    gl_Position  = vec4(1, 1, 0, 1);\n"
        "    EmitVertex();\n"
        "}\n"
        "\n";
    static const GLchar *tcs = "#version 430 core\n"
                               "#extension GL_ARB_enhanced_layouts : require\n"
                               "\n"
                               "layout(vertices = 1) out;\n"
                               "\n"
                               "in  vec4 vs_tcs[];\n"
                               "out vec4 tcs_tes[];\n"
                               "\n"
                               "void main()\n"
