#if 0
    static const GLchar* tcs_tested =
        "#version 430 core\n"
        "#extension GL_ARB_enhanced_layouts : require\n"
        "\n"
        "layout(vertices = 1) out;\n"
        "\n"
        "VAR_DEFINITION"
        "\n"
        "in  vec4 vs_tcs[];\n"
        "out vec4 tcs_tes[];\n"
        "\n"
        "void main()\n"
        "{\n"
        "    vec4 result = vs_tcs[gl_InvocationID];\n"
