                                      "}\n"
                                      "\n";

    std::string source;
    Utils::Shader::STAGES test_case = m_test_cases[test_case_index];

    if (test_case == stage)
    {
        const GLchar *array = "";
        const GLchar *index = "";
        size_t position     = 0;
        size_t temp;
        // It is a compile time error to apply xfb_offset to the declaration of an unsized array(GLSL4.5 spec: Page73)
        // change array = "[]" to "[1]"
        switch (stage)
        {
        case Utils::Shader::GEOMETRY:
            source = gs_tested;
            array  = "[1]";
            index  = "[0]";
