GPUShaderFP64Test6::GPUShaderFP64Test6(deqp::Context &context)
    : TestCase(context, "illegal_conversions",
               "Verifies that invalid casts to double-precision variables are detected "
               "during compilation time.")
    , m_cs_id(0)
