                        m_context.getTestContext().getLog()
                            << tcu::TestLog::Message << &log[0] << tcu::TestLog::EndMessage;
                    }
                }
            }

            GLint length;
            glGetProgramiv(program, GL_INFO_LOG_LENGTH, &length);
