               "   mediump mat3 c;                     \n"
               "   mediump float d[2];                 \n"
               "};                             \n"
               "struct UU {                    \n"
               "   U a;                        \n"
               "   U b[2];                     \n"
               "   uvec2 c;                    \n"
               "};                             \n"
               ""
               "layout(binding=4) buffer TrickyBuffer {          \n"
               "   UU a[3];                                      \n"
               "   mediump mat4 b;                               \n"
               "   uint c;                                       \n"
               "} e[2];                                          \n"
               ""
               "layout(binding = 0) buffer SimpleBuffer {                \n"
               "   mediump mat3x2 a;                                     \n"
