}

// === Methods ===

GeometryShaderGetProgramiv2Test::GeometryShaderGetProgramiv2Test(Context &context, const ExtParameters &extParams,
                                                                 const char *name, const char *description)
    : TestCaseBase(context, extParams, name, description)
    , m_fs_id(0)
    , m_po_id(0)
    , m_vs_id(0)
{
}

void GeometryShaderGetProgramiv2Test::deinit()
{
    const glw::Functions &gl = m_context.getRenderContext().getFunctions();

    if (m_fs_id != 0)
    {
        gl.deleteShader(m_fs_id);

        m_fs_id = 0;
    }

    if (m_po_id != 0)
    {
        gl.deleteProgram(m_po_id);

        m_po_id = 0;
    }

    if (m_vs_id != 0)
    {
        gl.deleteShader(m_vs_id);

        m_vs_id = 0;
    }

    /* Release base class */
    TestCaseBase::deinit();
}

tcu::TestNode::IterateResult GeometryShaderGetProgramiv2Test::iterate()
{
    const glw::Functions &gl    = m_context.getRenderContext().getFunctions();
    const glw::GLenum pnames[]  = {m_glExtTokens.GEOMETRY_LINKED_VERTICES_OUT, m_glExtTokens.GEOMETRY_LINKED_INPUT_TYPE,
                                   m_glExtTokens.GEOMETRY_LINKED_OUTPUT_TYPE, m_glExtTokens.GEOMETRY_SHADER_INVOCATIONS};
    const unsigned int n_pnames = sizeof(pnames) / sizeof(pnames[0]);
    bool result                 = true;

    /* This test should only run if EXT_geometry_shader is supported. */
    if (!m_is_geometry_shader_extension_supported)
    {
        throw tcu::NotSupportedError(GEOMETRY_SHADER_EXTENSION_NOT_SUPPORTED, "", __FILE__, __LINE__);
    }

    /* Initialize the program object */
    std::string specialized_minimal_fs     = specializeShader(1,
                                                              /* parts */ &minimal_fs_code);
    const char *specialized_minimal_fs_raw = specialized_minimal_fs.c_str();
    std::string specialized_minimal_vs     = specializeShader(1,
                                                              /* parts */ &minimal_vs_code);
    const char *specialized_minimal_vs_raw = specialized_minimal_vs.c_str();

    m_fs_id = gl.createShader(GL_FRAGMENT_SHADER);
    m_vs_id = gl.createShader(GL_VERTEX_SHADER);

    GLU_EXPECT_NO_ERROR(gl.getError(), "glCreateShader() call(s) failed.");

    m_po_id = gl.createProgram();

    GLU_EXPECT_NO_ERROR(gl.getError(), "glCreateProgram() call failed.");

    if (!TestCaseBase::buildProgram(m_po_id, m_fs_id, 1, &specialized_minimal_fs_raw, m_vs_id, 1,
                                    &specialized_minimal_vs_raw))
    {
        m_testCtx.getLog() << tcu::TestLog::Message << "Failed to build a minimal test program object"
                           << tcu::TestLog::EndMessage;

        result = false;
        goto end;
    }

    /* Verify that GS-specific queries cause a GL_INVALID_OPERATION error
     * for a linked PO lacking the GS stage.
     */
    for (unsigned int n_pname = 0; n_pname < n_pnames; ++n_pname)
    {
        glw::GLenum error_code = GL_NO_ERROR;
        glw::GLenum pname      = pnames[n_pname];
        glw::GLint rv          = -1;

        gl.getProgramiv(m_po_id, pname, &rv);

        error_code = gl.getError();

        if (error_code != GL_INVALID_OPERATION)
        {
            m_testCtx.getLog() << tcu::TestLog::Message << "No error generated by glGetProgramiv() for pname [" << pname
                               << "]" << tcu::TestLog::EndMessage;

            result = false;
        }
    } /* for (all pnames) */

end:
    if (result)
    {
        m_testCtx.setTestResult(QP_TEST_RESULT_PASS, "Pass");
    }
    else
    {
        m_testCtx.setTestResult(QP_TEST_RESULT_FAIL, "Fail");
    }

    return STOP;
}

