    {
        FRAGMENT_SHADER_TYPE,
        VERTEX_SHADER_TYPE,
        COMPUTE_SHADER_TYPE,
        GEOMETRY_SHADER_TYPE,
        TESSELATION_CONTROL_SHADER_TYPE,
        TESSELATION_EVALUATION_SHADER_TYPE,

        /* */
        SHADER_TYPE_LAST
    };

