    static const char *str_GL_TEXTURE_MIN_LOD            = "GL_TEXTURE_MIN_LOD";
    static const char *str_UNKNOWN                       = "UNKNOWN";

    if (pname == m_glExtTokens.TEXTURE_BORDER_COLOR)
    {
        return str_GL_TEXTURE_BORDER_COLOR_EXT;
    }

    switch (pname)
