    case GL_TEXTURE_BASE_LEVEL:
        return str_GL_TEXTURE_BASE_LEVEL;
    case GL_TEXTURE_MIN_FILTER:
        return str_GL_TEXTURE_MIN_FILTER;
    case GL_TEXTURE_IMMUTABLE_FORMAT:
        return str_GL_TEXTURE_IMMUTABLE_FORMAT;
